pub type Result<T>=std::result::Result<T,String>;
fn need(v:bool,c:&str)->Result<()>{if v{Ok(())}else{Err(c.into())}}
fn identifier(v:&str)->bool{!v.is_empty()&&!v.starts_with('0')&&v.bytes().all(|b|b.is_ascii_digit())&&v.parse::<u64>().is_ok_and(|n|n<=9007199254740991)}
pub fn clock(at:&str)->Result<i64>{let t=chrono::DateTime::parse_from_rfc3339(at).map_err(|_|"SERVICE_CLOCK")?;need(t.to_rfc3339_opts(chrono::SecondsFormat::Millis,true)==at,"SERVICE_CLOCK")?;Ok(t.timestamp_millis())}
pub fn now()->String{chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
