#[derive(Clone,Deserialize,Serialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct Config{pub schema_version:u8,pub mode:String,pub runtime_dir:PathBuf,pub tournament_id:String,pub tournament_slug:String,pub exchanges:BTreeMap<String,String>,pub port:u16,pub maximum_book_slots:usize,#[serde(default)]pub stop_paths:Vec<PathBuf>,#[serde(default)]pub cohorts:Vec<CohortConfig>,#[serde(default)]pub writes_enabled:bool,#[serde(default)]pub migration:Option<network::MigrationPermit>,#[serde(default)]pub account_extras:bool,#[serde(default)]pub public_source_import:Option<PrefixBinding>}
impl Config{pub fn validate(&self)->Result<()>{need(self.schema_version==1&&["offline_replay","network_read_only"].contains(&self.mode.as_str())&&!self.writes_enabled,"SERVICE_READ_ONLY_CONFIGURATION_REQUIRED")?;need(self.runtime_dir.is_absolute()&&self.port>=1024&&self.maximum_book_slots==4&&self.stop_paths.iter().all(|p|p.is_absolute()),"SERVICE_CONFIGURATION")?;need(self.tournament_id=="bda92870-621e-47b0-bc3c-3602c5c26f55"&&self.tournament_slug=="midterm-elections"&&!self.exchanges.is_empty()&&self.exchanges.len()<=10000&&self.exchanges.iter().all(|(e,m)|identifier(e)&&identifier(m)),"SERVICE_SCOPE")?;let mut names=std::collections::HashSet::new();for c in &self.cohorts{need(c.id.len()>=2&&c.id.len()<=64&&c.id.as_bytes()[0].is_ascii_lowercase()&&c.id.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'-')&&names.insert(c.id.clone())&&["dual_no_v1","dual_no_v2","settlement_portfolio"].contains(&c.kind.as_str())&&c.bank_path.is_absolute(),"SERVICE_COHORT_SCOPE")?;}Ok(())}
 pub fn universe(&self)->Value{json!({"tournamentId":self.tournament_id,"exchanges":self.exchanges.iter().map(|(e,m)|json!({"marketId":m,"exchangeId":e,"option":"YES"})).collect::<Vec<_>>()})}}
enum Engine{Dual{bank:Value,state:Value,bank_hash:String,legacy:bool},Portfolio(PortfolioEngine)}
impl Engine{
 fn new(c:&CohortConfig,bank:Value)->Result<Self>{if c.kind.starts_with("dual_no_"){need(canonical_hash(&bank)==c.bank_hash,"SERVICE_BANK_HASH")?;let legacy=c.kind=="dual_no_v1";let state=if legacy{baal_portfolio_engine::dual_v1::create(&bank)?}else{dual_no::create(&bank)?};Ok(Self::Dual{bank,state,bank_hash:c.bank_hash.clone(),legacy})}else{need(digest(&bank)==c.bank_hash,"SERVICE_BANK_HASH")?;Ok(Self::Portfolio(PortfolioEngine::new(bank)?))}}
 fn state(&self)->Value{match self{Self::Dual{state,..}=>state.clone(),Self::Portfolio(e)=>e.state().clone()}}
 fn apply(&mut self,event:&Value,row:Option<&Value>,at:&str,account:Option<&Value>)->Result<Value>{match self{Self::Dual{bank,state,bank_hash,legacy}=>{*state=if *legacy{baal_portfolio_engine::dual_v1::advance(state,event,bank)?}else{dual_no::advance_frozen(state,event,bank,bank_hash)?};Ok(state.clone())},Self::Portfolio(e)=>{let r=row.ok_or("SERVICE_PORTFOLIO_BOUNDARY_PENDING")?;e.apply_with_entry_permission(r,at,account,event["allowNewEntries"].as_bool().unwrap_or(false))}}}
 fn report(&self,at:&str)->Result<Value>{match self{Self::Dual{bank,state,legacy,..}=>if *legacy{baal_portfolio_engine::dual_v1::report(state,bank,&json!(at))}else{dual_no::report(state,bank,&json!(at))},Self::Portfolio(e)=>e.report(at)}}
}
