fn frozen(c:&CohortConfig)->Result<()>{need(sha(&fs::read(&c.bank_path).map_err(|_|"SERVICE_BANK_READ")?)==c.bank_file_hash,"SERVICE_BANK_FILE_CHANGED")?;for pin in &c.source_pins{need(pin.path.is_absolute()&&sha(&fs::read(&pin.path).map_err(|_|"SERVICE_PIN_READ")?)==pin.sha256,"SERVICE_CODE_PIN_CHANGED")?;}Ok(())}
pub struct Service{pub config:Config,publisher:Publisher,source_journal:OwnedJournal,account_journal:OwnedJournal,cohorts:Vec<Cohort>,pub account:Option<Value>,pub account_view:Value,pub cycles:u64,pub status:String,pub derived:Arc<RwLock<Value>>,session:String,owner:OwnerLock}
impl Service{
 pub fn open(config:Config)->Result<Self>{config.validate()?;fs::create_dir_all(&config.runtime_dir).map_err(|_|"SERVICE_RUNTIME_DIRECTORY")?;let mut stops=config.stop_paths.clone();stops.push(config.runtime_dir.join("STOP"));need(!stops.iter().any(|p|p.exists()),"SERVICE_STOPPED")?;let owner=OwnerLock::acquire(&config.runtime_dir.join("baal-service.lock"))?;let token=owner.token().to_owned();let mut publisher=Publisher::new(&config.universe())?;let source_path=config.runtime_dir.join("rust-public-source.jsonl");let mut source_journal=OwnedJournal::open(&source_path,&token,&stops)?;
  if source_journal.status()["sequence"].as_u64().unwrap_or(0)>0{journal_rows(&source_path,|row|{if row["event"]["kind"]=="imported_public_prefix"{need(row["sequence"]==1,"SERVICE_SOURCE_IMPORT_GENESIS")?;let pin:PrefixBinding=serde_json::from_value(row["event"]["binding"].clone()).map_err(|_|"SERVICE_SOURCE_IMPORT")?;publisher=Publisher::from_verified_prefix(&pin.path,pin.bytes,&pin.sha256,&config.universe())?;}else{need(row["event"]["kind"]=="source_publication","SERVICE_SOURCE_REPLAY")?;publisher.apply_record(&row["event"]["row"])?;}need(row["state"]["sourceSequence"]==publisher.status()["sequence"]&&row["state"]["sourceHash"]==publisher.status()["hash"],"SERVICE_SOURCE_STATE_MISMATCH")})?;}
  if source_journal.status()["sequence"]==0{if let Some(pin)=&config.public_source_import{need(pin.path.is_absolute()&&pin.bytes>0,"SERVICE_SOURCE_IMPORT")?;publisher=Publisher::from_verified_prefix(&pin.path,pin.bytes,&pin.sha256,&config.universe())?;let snapshot=publisher.status();source_journal.commit(json!({"sourceSequence":snapshot["sequence"],"sourceHash":snapshot["hash"]}),json!({"kind":"imported_public_prefix","binding":pin}),snapshot["lastAt"].as_str().ok_or("SERVICE_SOURCE_IMPORT_CLOCK")?)?;}}let account_journal=OwnedJournal::open(&config.runtime_dir.join("rust-account-eligibility.jsonl"),&token,&stops)?;let mut cohorts=Vec::new();for c in &config.cohorts{frozen(c)?;let bank=read_json(&c.bank_path)?;need(bank["mode"]!="funded_settlement_value_paper_v1","SERVICE_AUTHORITATIVE_VALUE_REVISION_IMPORT_REQUIRED")?;let cutoff=clock(bank["cutoff"].as_str().ok_or("SERVICE_BANK_CUTOFF")?)?;let mut import_evidence=None;let mut engine=if let Some(import)=&c.history_import{need(c.kind=="settlement_portfolio"&&config.public_source_import.as_ref().is_some_and(|p|p.path==import.public_source.path&&p.bytes==import.public_source.bytes&&p.sha256==import.public_source.sha256),"SERVICE_IMPORT_SCOPE")?;let(engine,evidence)=baal_portfolio_engine::import_history(bank.clone(),&import.checkpoint.path,import.checkpoint.bytes,&import.checkpoint.sha256,&import.public_source.path,import.public_source.bytes,&import.public_source.sha256)?;import_evidence=Some(serde_json::to_value(evidence).map_err(|_|"SERVICE_IMPORT_EVIDENCE")?);Engine::Portfolio(engine)}else{Engine::new(c,bank.clone())?};let dir=config.runtime_dir.join("cohorts").join(&c.id);fs::create_dir_all(&dir).map_err(|_|"SERVICE_COHORT_DIRECTORY")?;let path=dir.join("journal.jsonl");let journal=OwnedJournal::open(&path,&token,&stops)?;let mut source_sequence=import_evidence.as_ref().and_then(|v|v["walletSourceSequence"].as_u64()).unwrap_or_else(||bank["sourcePrefixSequence"].as_u64().unwrap_or(0));let mut source_hash=import_evidence.as_ref().and_then(|v|v["walletSourceHash"].as_str()).unwrap_or_else(||bank["sourcePrefixTailHash"].as_str().unwrap_or("")).to_owned();if journal.status()["sequence"].as_u64().unwrap_or(0)>0{journal_rows(&path,|row|{let ev=&row["event"];if ev["kind"]=="genesis"||ev["kind"]=="imported_opening"{need(row["sequence"]==1&&ev["bankHash"]==c.bank_hash&&canonical_hash(&row["state"]["paper"])==canonical_hash(&engine.state()),"SERVICE_COHORT_GENESIS")?;}else{let next=engine.apply(&ev["engineEvent"],ev.get("publication"),ev["availableAt"].as_str().ok_or("SERVICE_REPLAY_CLOCK")?,ev.get("account"))?;need(canonical_hash(&next)==canonical_hash(&row["state"]["paper"]),"SERVICE_ECONOMIC_REPLAY_MISMATCH")?;source_sequence=row["state"]["sourceSequence"].as_u64().ok_or("SERVICE_SOURCE_FRONTIER")?;source_hash=row["state"]["sourceHash"].as_str().ok_or("SERVICE_SOURCE_FRONTIER")?.to_owned();}Ok(())})?;}
   let mut cohort=Cohort{config:c.clone(),engine,journal,source_sequence,source_hash,cutoff};if cohort.journal.status()["sequence"].as_u64().unwrap_or(0)==0{cohort.journal.commit(json!({"paper":cohort.engine.state(),"sourceSequence":cohort.source_sequence,"sourceHash":cohort.source_hash}),json!({"kind":if import_evidence.is_some(){"imported_opening"}else{"genesis"},"bankHash":c.bank_hash,"cutoff":bank["cutoff"],"originalImport":import_evidence}),cohort.engine.state()["lastAvailableAt"].as_str().unwrap_or_else(||bank["cutoff"].as_str().unwrap()))?;}cohorts.push(cohort);}
  let out=Self{config,owner,publisher,source_journal,account_journal,cohorts,account:None,account_view:json!({"mode":"official_account","available":false,"collectorStatus":"offline","health":{"status":"unavailable"},"positions":[],"pending":[],"trades":[],"sourceTimes":{},"errors":{}}),cycles:0,status:"running".into(),derived:Arc::new(RwLock::new(json!({}))),session:format!("rust-{}-{}",std::process::id(),chrono::Utc::now().timestamp_millis())};out.publish(&now())?;Ok(out)}
 pub fn guard(&self)->Result<()>{self.owner.check()?;need(self.status=="running","SERVICE_FAILED_RECONCILE_REQUIRED")?;need(!self.config.runtime_dir.join("STOP").exists()&&!self.config.stop_paths.iter().any(|p|p.exists()),"SERVICE_STOPPED")?;for c in &self.cohorts{frozen(&c.config)?;}Ok(())}
 pub fn source_status(&self)->Value{self.publisher.status()}
 pub fn record_account(&mut self,at:&str)->Result<()>{self.guard()?;self.account_journal.commit(json!({"snapshot":self.account,"availableAt":at}),json!({"kind":"sanitized_account_eligibility"}),at)?;atomic_json(&self.config.runtime_dir.join("official-account.json"),&self.account_view)}
 pub fn focus_markets(&self,at:&str)->Result<Vec<String>>{let time=clock(at)?;let mut risk=Vec::new();let mut candidates=Vec::new();for c in &self.cohorts{let bank=read_json(&c.config.bank_path)?;let state=c.engine.state();if c.config.kind.starts_with("dual_no_"){let owned=state["positions"].as_object().is_some_and(|o|!o.is_empty())||!state["pending"].is_null()||!state["package"].is_null();for leg in bank["review"]["legs"].as_array().ok_or("SERVICE_PAIR_SCOPE")?{let market=leg["marketId"].as_str().ok_or("SERVICE_PAIR_SCOPE")?.to_owned();if owned{risk.push(market)}else if c.config.entry_enabled&&!c.config.entry_drain_path.as_ref().is_some_and(|p|p.exists())&&time<clock(bank["review"]["expiresAt"].as_str().ok_or("SERVICE_PAIR_CLOCK")?)?{candidates.push(market)}}}else{if let Some(wallets)=state["wallets"].as_object(){for w in wallets.values(){for key in ["positions","pending"]{if let Some(rows)=w[key].as_object(){risk.extend(rows.keys().cloned());}}}}for r in bank["research"].as_array().ok_or("SERVICE_RESEARCH_SCOPE")?{if c.config.entry_enabled&&!c.config.entry_drain_path.as_ref().is_some_and(|p|p.exists())&&time<clock(r["expiresAt"].as_str().ok_or("SERVICE_RESEARCH_CLOCK")?)?{candidates.push(r["marketId"].as_str().ok_or("SERVICE_RESEARCH_SCOPE")?.to_owned());}}}}
 let mut output=Vec::new();for m in risk.into_iter().chain(candidates){if !output.contains(&m){output.push(m)}}if output.len()<4{let all=self.config.exchanges.values().cloned().collect::<Vec<_>>();for i in 0..all.len(){let market=all[(self.cycles as usize+i)%all.len()].clone();if !output.contains(&market){output.push(market)}if output.len()>=4{break}}}output.truncate(4);Ok(output)}
 
 pub fn ingest(&mut self,row:Value,account:Option<Value>)->Result<()>{let result=self.ingest_inner(row,account);if result.is_err(){self.status="failed".into();}result}
 fn ingest_inner(&mut self,row:Value,account:Option<Value>)->Result<()>{self.guard()?;let at=row["at"].as_str().ok_or("SERVICE_PUBLICATION_CLOCK")?.to_owned();let sequence=row["sequence"].as_u64().ok_or("SERVICE_SOURCE_FRONTIER")?;self.publisher.apply_record(&row)?;self.source_journal.commit(json!({"sourceSequence":sequence,"sourceHash":row["hash"]}),json!({"kind":"source_publication","row":row}),&at)?;self.account=account.clone();let books=self.publisher.status()["books"].clone();for cohort in &mut self.cohorts{if clock(&at)?<cohort.cutoff||sequence<=cohort.source_sequence{continue}let is_book=row["kind"]=="book";let allow_entries=cohort.config.entry_enabled&&!cohort.config.entry_drain_path.as_ref().is_some_and(|p|p.exists());let mut event=if is_book{let book=&row["payload"]["book"];let bank=read_json(&cohort.config.bank_path)?;let pairs=bank["review"]["legs"].as_array().map(|legs|legs.iter().filter_map(|l|books.get(format!("{}:YES",l["exchangeId"].as_str().unwrap_or("")).as_str()).cloned()).collect::<Vec<_>>()).unwrap_or_default();json!({"kind":"book","book":book,"pairBooks":pairs,"availableAt":at,"accountEligibility":account,"admission":{"positiveConditionalCapacity":false},"allowNewEntries":allow_entries})}else{json!({"kind":"boundary","availableAt":at,"allowNewEntries":false})};
   if is_book&&cohort.config.kind.starts_with("dual_no_"){let bank=read_json(&cohort.config.bank_path)?;if allow_entries{let pair=event["pairBooks"].as_array().cloned().unwrap_or_default();event["admission"]=baal_portfolio_engine::dual_capacity(&bank["review"],&bank["capacityPolicy"],&pair,account.as_ref(),&at).unwrap_or_else(|_|json!({"positiveConditionalCapacity":false}));}if !bank["review"]["legs"].as_array().unwrap().iter().any(|l|l["exchangeId"]==row["payload"]["book"]["exchangeId"]){continue}}
   let state=cohort.engine.apply(&event,Some(&row),&at,account.as_ref())?;cohort.journal.commit(json!({"paper":state,"sourceSequence":sequence,"sourceHash":row["hash"]}),json!({"kind":if is_book{"book"}else{"boundary"},"engineEvent":event,"publication":row,"account":account,"availableAt":at}),&at)?;cohort.source_sequence=sequence;cohort.source_hash=row["hash"].as_str().unwrap_or("").into();}
  self.cycles+=1;self.publish(&at)}
 pub fn emit(&mut self,kind:&str,payload:Value,at:&str)->Result<()>{let row=self.publisher.next_record(kind,payload,at,&self.session)?;self.ingest(row,self.account.clone())}
 pub fn start_session(&mut self,at:&str)->Result<()>{self.emit("session_start",json!({"scope":self.publisher.status()["scope"]}),at)}
 pub fn publish(&self,at:&str)->Result<()>{let mut reports=Vec::new();for cohort in &self.cohorts{let report=cohort.engine.report(at)?;reports.push(json!({"id":cohort.config.id,"kind":cohort.config.kind,"bankHash":cohort.config.bank_hash,"sourceSequence":cohort.source_sequence,"sourceHash":cohort.source_hash,"paper":true,"executionAuthority":false,"report":report}));atomic_json(&self.config.runtime_dir.join("cohorts").join(&cohort.config.id).join("stats.json"),&report)?;}let view=json!({"schemaVersion":1,"mode":"rust_baal_service","name":"Baal","updatedAt":at,"status":self.status,"runtime":{"pid":std::process::id(),"status":self.status,"language":"Rust","engineHash":env!("BAAL_SERVICE_ENGINE_HASH"),"cycles":self.cycles,"readOnly":true,"competitionOrders":0,"maximumOrdinaryBookSlots":4},"account":self.account_view,"execution":{"status":"DISABLED","reason":"prospective_rust_backend_no_activation","updatedAt":at,"ordersSubmitted":0,"dispatchAttempts":0,"unconfirmedIntents":0,"fills":[],"realizedPnl":"0.000000"},"cohorts":reports,"source":self.publisher.status()});atomic_json(&self.config.runtime_dir.join("rust-service-stats.json"),&view)?;*self.derived.write().map_err(|_|"SERVICE_STATUS_LOCK")?=view;Ok(())}
}
pub struct HttpServer{pub port:u16,stop:Arc<AtomicBool>,thread:Option<thread::JoinHandle<()>>}
impl HttpServer{pub fn start(port:u16,view:Arc<RwLock<Value>>)->Result<Self>{let listener=TcpListener::bind(("127.0.0.1",port)).map_err(|_|"SERVICE_HTTP_BIND")?;let port=listener.local_addr().unwrap().port();listener.set_nonblocking(true).map_err(|_|"SERVICE_HTTP_BIND")?;let stop=Arc::new(AtomicBool::new(false));let flag=stop.clone();let thread=thread::spawn(move||{while !flag.load(Ordering::Relaxed){match listener.accept(){Ok((mut stream,peer))=>{if peer.ip().is_loopback(){let _=serve(&mut stream,&view);}},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>thread::sleep(Duration::from_millis(10)),Err(_)=>break}}});Ok(Self{port,stop,thread:Some(thread)})}}
impl Drop for HttpServer{fn drop(&mut self){self.stop.store(true,Ordering::Relaxed);if let Some(t)=self.thread.take(){let _=t.join();}}}
fn serve(stream:&mut TcpStream,view:&Arc<RwLock<Value>>)->Result<()>{stream.set_nonblocking(false).map_err(|_|"SERVICE_HTTP_IO")?;stream.set_read_timeout(Some(Duration::from_millis(250))).map_err(|_|"SERVICE_HTTP_IO")?;stream.set_write_timeout(Some(Duration::from_secs(2))).map_err(|_|"SERVICE_HTTP_IO")?;let mut bytes=[0u8;8192];let n=stream.read(&mut bytes).map_err(|_|"SERVICE_HTTP_IO")?;let raw=std::str::from_utf8(&bytes[..n]).map_err(|_|"SERVICE_HTTP_REQUEST")?;let line=raw.lines().next().unwrap_or("");let mut parts=line.split_whitespace();let method=parts.next().unwrap_or("");let url=parts.next().unwrap_or("");let status=view.read().map_err(|_|"SERVICE_STATUS_LOCK")?;let (code,body)=if method!="GET"{(405,json!({"error":"READ_ONLY"}))}else{match url{"/health"=>(200,json!({"status":status["status"],"language":"Rust","engineHash":status["runtime"]["engineHash"]})),"/api/stats"|"/api/rust"=>(200,status.clone()),"/api/account"=>(200,status["account"].clone()),"/api/execution"=>(200,status["execution"].clone()),"/api/wallets"=>(200,json!({"updatedAt":status["updatedAt"],"cohorts":status["cohorts"],"execution":status["execution"]})),_ if url.starts_with("/api/cohorts/")=>{let id=url.trim_start_matches("/api/cohorts/");status["cohorts"].as_array().and_then(|a|a.iter().find(|x|x["id"]==id)).map(|v|(200,v.clone())).unwrap_or((404,json!({"available":false})))},_=>(404,json!({"available":false,"reason":"unported_or_unknown_endpoint"}))}};let body=serde_json::to_vec(&body).map_err(|_|"SERVICE_HTTP_RESPONSE")?;write!(stream,"HTTP/1.1 {code}\r\nContent-Type: application/json\r\nCache-Control: no-store\r\nConnection: close\r\nContent-Length: {}\r\n\r\n",body.len()).and_then(|_|stream.write_all(&body)).map_err(|_|"SERVICE_HTTP_IO".into())}

pub fn need_network_configuration(config:&Config,enabled:bool)->Result<()>{need(enabled&&config.mode=="network_read_only"&&!config.writes_enabled,"SERVICE_EXPLICIT_READ_MIGRATION_REQUIRED")?;let permit=config.migration.as_ref().ok_or("SERVICE_MIGRATION_PERMIT_REQUIRED")?;let time=clock(&now())?;need(permit.owner=="Codex"&&!permit.handoff_id.is_empty()&&clock(&permit.observed_at)?<=time&&clock(&permit.expires_at)?>time&&permit.legacy_lock_path.is_absolute()&&permit.legacy_stop_path.is_absolute()&&permit.legacy_rate_path.is_absolute()&&!permit.legacy_lock_path.exists()&&permit.legacy_stop_path.is_file(),"SERVICE_LEGACY_OWNER_NOT_RELEASED")?;let root=PathBuf::from(std::env::var_os("LOCALAPPDATA").ok_or("SERVICE_APPROVED_RUNTIME")?).join("SigTradingCup");need(config.runtime_dir.starts_with(&root)&&config.runtime_dir!=root.join("paper-runtime"),"SERVICE_SEPARATE_APPROVED_RUNTIME_REQUIRED")}

